-- Keep every no-actions view synchronized so these negatives exercise frozen
-- authority, rather than merely disagreeing with a copied final World.
create function pg_temp.alter_guard_world(p_attempt jsonb,p_path text[],p_value jsonb)
returns jsonb language plpgsql as $$
declare attempt jsonb:=p_attempt; world jsonb; i integer;
begin
 world:=jsonb_set(attempt#>'{paths,0,initialWorld}',p_path,p_value);
 attempt:=jsonb_set(attempt,'{paths,0,initialWorld}',world);
 attempt:=jsonb_set(attempt,'{paths,0,sourceBoundary}',world->'realityBoundarySnapshot');
 for i in 0..2 loop attempt:=jsonb_set(attempt,array['paths','0','trajectories',i::text,'finalWorld'],world); end loop;
 return attempt;
end; $$;



