set local role authenticated;
insert into world_guard_context(source) select public.digital_life_model_draft_source_v2();
update world_guard_context set rules=$rules${"version":"digital-life-rules-v3","graphSnapshotId":"33333333-3333-4333-8333-333333333333","agentSnapshotId":"44444444-4444-4444-8444-444444444444","profileRevision":2,"strategies":[],"actions":[{"key":"rule-1","pathKey":"main","actorKey":"person-1","when":{"kind":"at_tick","tickIndex":0},"operation":{"actionType":"update_commitment","commitmentKey":"commitment-1","label":"保留安排","status":"active"},"guard":{"kind":"resource_balance","resourceKey":"resource-1","operator":"lte","value":4},"classification":"assumption","confirmedForSimulation":true,"evidenceSummary":"本人明确设定的条件"}]}$rules$::jsonb||jsonb_build_object('graphSnapshotId',source#>'{relation_graph_snapshots,id}','agentSnapshotId',source#>'{relation_graph_snapshots,agent_snapshot_id}','profileRevision',source#>'{reality_profiles,revision}');
update world_guard_context set rules=jsonb_set(rules,'{actions,0,actorKey}',(select to_jsonb('person-'||ord::text) from jsonb_array_elements(source->'agent_profiles') with ordinality t(a,ord) where a->>'agent_type'='user_core'));
update world_guard_context set request=jsonb_build_object('graph_snapshot_id',rules->'graphSnapshotId','idempotency_key','00000000-0000-4000-8000-00000000f921','horizon_days',30,'digital_life_rules',rules);

select ok(public.formal_world_guard_shape_valid_v3('{"kind":"resource_balance","resourceKey":"resource-1","operator":"lte","value":4}'),'strict resource guard accepted');
select ok(public.formal_world_guard_shape_valid_v3('{"kind":"environment_equals","variableKey":"pressure-1","value":"当前安排稳定"}'),'strict environment guard accepted');
select ok(not public.formal_world_guard_shape_valid_v3(null),'SQL NULL guard is invalid');
