select ok(public.formal_run_rules_valid((select rules from world_guard_context)),'v3 guards pass the real common shape dispatcher');
select ok(not public.formal_run_rules_valid(jsonb_set((select rules from world_guard_context),'{version}','"digital-life-rules-v2"')),'v2 cannot acquire a guard');
select ok(public.formal_world_guard_rules_valid_v3((select source from world_guard_context),(select rules from world_guard_context),30),'source-bound self guard accepted');
select ok(not public.formal_world_guard_rules_valid_v3((select source from world_guard_context),jsonb_set((select rules from world_guard_context),'{actions,0,guard,value}','0'),30),'guard threshold below declared minimum rejected');
select ok(not public.formal_world_guard_rules_valid_v3((select source from world_guard_context),jsonb_set((select rules from world_guard_context),'{actions,0,guard,value}','9'),30),'guard threshold above declared maximum rejected');
select ok(not public.formal_world_guard_rules_valid_v3((select source from world_guard_context),jsonb_set((select rules from world_guard_context),'{actions,0,actorKey}',(select to_jsonb('person-'||ord::text) from world_guard_context c cross join lateral jsonb_array_elements(c.source->'agent_profiles') with ordinality t(a,ord) where a->>'agent_type'='npc' limit 1)),30),'NPC guard is rejected');
select is(public.formal_world_guard_description_v3((select rules#>'{actions,0,guard}' from world_guard_context),(select source from world_guard_context)),'可投入时间余额不高于4小时','SQL condition description matches the actual TS formatter');
