select is((select source->'signature' from world_guard_context),public.digital_life_model_draft_source_v1()->'signature','v1 source signature remains unchanged');
select is((select source->'signature_v2' from world_guard_context),public.digital_life_model_draft_source_v2()->'signature_v2','v3 does not introduce a source-v3 hash');

-- Atomic reservation and terminal receipt integration. These execute only in a real local DB.
