select ok(not public.formal_world_guard_rules_valid_v3(jsonb_set((select source from world_guard_context),'{reality_profiles,pressures}','[{"value":"当前安排稳定","classification":"fact","evidenceSummary":"本人明确记录"}]'),jsonb_set((select rules from world_guard_context),'{actions,0,guard}','{"kind":"environment_equals","variableKey":"pressure-1","value":"未声明的替代值"}'),30),'guard cannot invent an environment alternative');
select ok(public.formal_world_guard_rules_valid_v3(jsonb_set((select source from world_guard_context),'{reality_profiles,world_model_inputs,resources,0,classification}','"fact"'),(select rules from world_guard_context),30),'fact resource keeps the same declared numeric guard bounds');
