update world_guard_context set attempt=pg_temp.guard_attempt(source,(reservation->>'accepted_at')::timestamptz,(reservation->>'simulation_start_at')::timestamptz,
 ((('x'||left(encode(extensions.digest(convert_to((request->>'graph_snapshot_id')||':'||(request->>'idempotency_key'),'UTF8'),'sha256'),'hex'),7))::bit(28)::integer % 1999999999)+1));
select ok((select public.formal_world_guard_attempt_diagnostics_v3(attempt,source,(reservation->>'accepted_at')::timestamptz,(reservation->>'simulation_start_at')::timestamptz,30,(attempt#>>'{paths,0,inputSnapshot,deterministicSeed}')::integer) is not null from world_guard_context),'real Core no_actions fixture validates against the exact frozen source');
select ok((select public.formal_world_guard_initial_authority_v3(attempt#>'{paths,0,initialWorld}',source,rules,'main','formal-'||(attempt#>>'{paths,0,causalFingerprint}'),(reservation->>'simulation_start_at')::timestamptz,30) from world_guard_context),'the source-bound full initial authority admits the positive runtime-shaped fixture');
select is((select attempt#>'{paths,0,inputSnapshot,digitalLifeModel}' from world_guard_context),(select public.formal_world_guard_model_v3(source,rules) from world_guard_context),'complete model background and ordered people/relations match the frozen source');
select ok((select public.formal_world_guard_attempt_diagnostics_v3(pg_temp.alter_guard_world(attempt,string_to_array(probe.path,','),probe.replacement),source,(reservation->>'accepted_at')::timestamptz,(reservation->>'simulation_start_at')::timestamptz,30,(attempt#>>'{paths,0,inputSnapshot,deterministicSeed}')::integer) is null from world_guard_context),probe.description)
from (values
 ('agentDefinitions,1,displayName','"来源中没有的人物名称"'::jsonb,'synchronized actor definition forgery is rejected'),
 ('agentStates,1,commitments','[{"id":"forged","label":"虚构安排","status":"planned"}]'::jsonb,'synchronized initial NPC commitment forgery is rejected'),
 ('entities,1,label','"来源中没有的实体名称"'::jsonb,'synchronized entity forgery is rejected'),
 ('relations,0,signal','"negative"'::jsonb,'synchronized locked initial relation signal forgery is rejected'),
 ('constraints','[{"id":"forged"}]'::jsonb,'synchronized undeclared initial constraint is rejected'),
 ('externalVariables','[{"id":"forged"}]'::jsonb,'synchronized undeclared initial variable is rejected'),
 ('realityBoundarySnapshot,evidenceLedger,items,0,statement','"虚构来源事实"'::jsonb,'synchronized real-evidence source body forgery is rejected'),
 ('realityBoundarySnapshot,assumptionLedger,assumptions,2,statement','"虚构行动假设"'::jsonb,'synchronized rule assumption body forgery is rejected')
) probe(path,replacement,description);
select ok((select public.formal_world_guard_attempt_diagnostics_v3(jsonb_set(attempt,'{paths,0,initialWorld,resources,0,available}','3'),source,(reservation->>'accepted_at')::timestamptz,(reservation->>'simulation_start_at')::timestamptz,30,(attempt#>>'{paths,0,inputSnapshot,deterministicSeed}')::integer) is null from world_guard_context),'tampered initial balance rejected before terminal write');
select ok((select public.formal_world_guard_attempt_diagnostics_v3(jsonb_set(attempt,'{paths,0,trajectories,0,steps,0,tickIndex}','1'),source,(reservation->>'accepted_at')::timestamptz,(reservation->>'simulation_start_at')::timestamptz,30,(attempt#>>'{paths,0,inputSnapshot,deterministicSeed}')::integer) is null from world_guard_context),'display or forged tick cannot replace actual Core tick zero');
select ok((select public.formal_world_guard_attempt_diagnostics_v3(jsonb_set(attempt,'{paths,0,trajectories,0,trajectorySeed}','1'),source,(reservation->>'accepted_at')::timestamptz,(reservation->>'simulation_start_at')::timestamptz,30,(attempt#>>'{paths,0,inputSnapshot,deterministicSeed}')::integer) is null from world_guard_context),'cross-sample seed rejected');
select throws_ok($$select public.finalize_account_sandbox_no_eligible_actions_v3((request->>'idempotency_key')::uuid,request,'{}') from world_guard_context$$,'P0001','invalid_no_actions_attempt','malformed attempt cannot create a known result');
select is((select count(*)::integer from public.simulations where user_id=auth.uid()),0,'failed finalizer creates no completed Run');
select is((select count(*)::integer from public.event_logs where user_id=auth.uid()),0,'failed finalizer creates no Event');
select is((select count(*)::integer from public.claims where user_id=auth.uid()),0,'failed finalizer creates no Claim');
select is((select count(*)::integer from public.reports where user_id=auth.uid()),0,'failed finalizer creates no Report');
select is((select run from public.reserve_account_sandbox_run((select (request->>'graph_snapshot_id')::uuid from world_guard_context),(select (request->>'idempotency_key')::uuid from world_guard_context),30,(select rules from world_guard_context),null,null)),null::jsonb,'invalid attempt leaves the original reservation queued');
update world_guard_context set receipt=public.finalize_account_sandbox_no_eligible_actions_v3((request->>'idempotency_key')::uuid,request,attempt);
select is((select receipt->'idempotent' from world_guard_context),'false'::jsonb,'first validated terminal result is appended');
select is((select receipt#>>'{pathDiagnostics,paths,0,status}' from world_guard_context),'no_actions','terminal result has no invented completion');
select is((select receipt#>'{pathDiagnostics,paths,0,guardObservations,samples,0,ticks,0,observations,0,guard}' from world_guard_context),'false'::jsonb,'safe guard observation derives the actual before World');
select is((select public.finalize_account_sandbox_no_eligible_actions_v3((request->>'idempotency_key')::uuid,request,'{}')->'pathDiagnostics' from world_guard_context),(select receipt->'pathDiagnostics' from world_guard_context),'exact original request replays its durable diagnostic without trusting a replacement attempt');
select throws_ok($$select public.finalize_account_sandbox_no_eligible_actions_v3((request->>'idempotency_key')::uuid,jsonb_set(request,'{horizon_days}','90'),attempt) from world_guard_context$$,'P0001','idempotency_key_content_conflict','same key with changed original content conflicts');
select is((select run->>'status' from public.reserve_account_sandbox_run((select (request->>'graph_snapshot_id')::uuid from world_guard_context),(select (request->>'idempotency_key')::uuid from world_guard_context),30,(select rules from world_guard_context),null,null)),'no_eligible_actions','v3 reservation replay returns the explicit terminal union');
select is((select count(*)::integer from public.simulations where user_id=auth.uid()),0,'successful terminal finalizer still creates no Run');
select set_config('app.formal_reservation_rpc','off',true);
select is((with changed as (update public.generation_jobs set formal_terminal_receipt='{}' where user_id=auth.uid() returning id) select count(*)::integer from changed),0,'gate-off authenticated UPDATE sees zero reservation rows under RLS');
select set_config('app.formal_reservation_rpc','on',true);
select is((select formal_terminal_receipt->'pathDiagnostics' from public.generation_jobs where user_id=auth.uid() and idempotency_key='00000000-0000-4000-8000-00000000f921'),(select receipt->'pathDiagnostics' from world_guard_context),'gate-off UPDATE leaves the stored receipt unchanged');
select throws_ok($$update public.generation_jobs set formal_terminal_receipt='{}' where user_id=auth.uid()$$,'42501',null,'even a forged generic reservation gate cannot rewrite a terminal receipt');
select set_config('app.formal_reservation_rpc','off',true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000f902',true);
select throws_ok($$select public.finalize_account_sandbox_no_eligible_actions_v3((request->>'idempotency_key')::uuid,request,attempt) from world_guard_context$$,'P0001','reservation_not_found','foreign owner cannot access the original terminal receipt');
reset role;
select throws_ok($$insert into public.generation_jobs(user_id,job_type,trace_id,version,writer_version,idempotency_key,formal_terminal_receipt) values('00000000-0000-0000-0000-00000000f901','guard_nonformal_probe','pg-test','pg-test','pg-test','guard-nonformal-probe','{}')$$,'23514',null,'non-formal jobs cannot store a terminal receipt even with owner privileges');
select ok(not has_function_privilege('anon','public.finalize_account_sandbox_no_eligible_actions_v3(uuid,jsonb,jsonb)','EXECUTE'),'anonymous terminal access is revoked');
select ok(not has_column_privilege('anon','public.generation_jobs','formal_terminal_receipt','UPDATE'),'anonymous receipt DML is revoked');
select ok(has_column_privilege('authenticated','public.generation_jobs','formal_terminal_receipt','UPDATE'),'authenticated gets only the dedicated receipt writer column');
select ok(not has_column_privilege('authenticated','public.generation_jobs','output_refs','UPDATE'),'generic job output_refs UPDATE remains unavailable');
select ok(not has_column_privilege('authenticated','public.generation_jobs','error_code','UPDATE'),'generic job error_code UPDATE remains unavailable');
select ok(not exists(select 1 from pg_proc where pronamespace='public'::regnamespace and (proname like 'formal_world_guard_%_v3' or proname='finalize_account_sandbox_no_eligible_actions_v3') and prosecdef),'all new helpers and finalizer use invoker permissions');
select * from finish();
rollback;
